def compute(vars):
    claim = vars["v1"]
    total = vars["v2"]

    if total == 0:
        return None

    ratio = claim / total
    percentage = ratio * 100

    return {
        "value": percentage,
        "trace": {
            "claim": claim,
            "total": total,
            "ratio": ratio,
            "percentage": percentage,
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": "percentage"
            }
        }
    }
